<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import{Clock,Search,Stethoscope}from'@lucide/vue';import{api,apiError,unpack}from'@/services/api';import type{ClinicalCase}from'@/types';import{useLocaleStore}from'@/stores/locale'
const cases=ref<ClinicalCase[]>([]),loading=ref(true),error=ref(''),query=ref(''),specialty=ref('All specialties'),locale=useLocaleStore()
const specialties=computed(()=>['All specialties',...new Set(cases.value.map(c=>c.specialty))]);const filtered=computed(()=>cases.value.filter(c=>(specialty.value==='All specialties'||c.specialty===specialty.value)&&`${c.title} ${c.subtitle}`.toLowerCase().includes(query.value.toLowerCase())))
onMounted(async()=>{try{cases.value=unpack(await api.getCases({status:'published'}))}catch(e){error.value=apiError(e)}finally{loading.value=false}})
</script>
<template><div class="page"><header class="page-header"><div><div class="page-eyebrow">{{ locale.t('Practice catalogue') }}</div><h1>{{ locale.t('Case library') }}</h1><p class="subtitle">{{ locale.t('Five structured medical histories, designed for Australian undergraduate clinical learning.') }}</p></div></header><div class="filter-row"><div class="field" style="position:relative"><Search :size="16" style="position:absolute;left:12px;top:14px;color:#84918c"/><input v-model="query" class="input" style="padding-left:36px" :placeholder="locale.t('Search cases…')" :aria-label="locale.t('Search cases')"></div><select v-model="specialty" class="select" :aria-label="locale.t('Filter by specialty')"><option v-for="s in specialties" :key="s">{{locale.t(s)}}</option></select></div><div v-if="error" class="alert alert--error">{{error}}</div><div v-if="loading" class="loading"><div class="spinner"></div></div><div v-else class="grid-3"><RouterLink v-for="item in filtered" :key="item.id" class="card case-card" :to="`/student/cases/${item.id}`"><div class="case-card__top"><span class="case-card__icon"><Stethoscope :size="20"/></span><span class="tag">{{locale.t(item.difficulty)}}</span></div><h3>{{item.title}}</h3><p>{{item.subtitle}}</p><div class="case-card__meta"><span>{{locale.t(item.specialty)}}</span><span><Clock :size="13"/>{{item.durationMinutes}} {{locale.t('min')}}</span></div></RouterLink></div><div v-if="!loading&&!filtered.length" class="card empty"><Search/><h3>{{ locale.t('No matching cases') }}</h3><p>{{ locale.t('Try a different search or specialty.') }}</p></div></div></template>
